// @ts-check
import { defineConfig } from 'astro/config';

// Fully static output — no SSR, no client framework. Every page is emitted as
// semantic HTML with JSON-LD in <head> at build time, satisfying the
// first-GET-without-JS rule. Deployable to Azure Static Web Apps as-is.
//
// sitemap.xml, feed.xml, llms.txt and llms-full.txt are generated by Astro
// endpoints (src/pages/*.ts) from the SAME content source as the pages
// (src/content/learn + src/data/site.ts), so they cannot drift.
export default defineConfig({
  site: 'https://www.mcpglimpse.com',
  output: 'static',
  trailingSlash: 'ignore',
  build: {
    format: 'directory',
  },
});
